#!/usr/bin/env node
'use strict';
// extract.js <elf-file>  -> prints JSON { "<addr>": <int32-or-uint32 value>, ... }
// Parses the ELF (32/64-bit, LE/BE) program headers, walks every PT_LOAD
// segment and emits every 4-byte aligned word from the file image, keyed by
// its virtual address.

const fs = require('fs');

function extract(path) {
  const buf = fs.readFileSync(path);
  if (buf.length < 52) throw new Error('file too small to be ELF');
  if (buf[0] !== 0x7f || buf[1] !== 0x45 || buf[2] !== 0x4c || buf[3] !== 0x46) {
    throw new Error('not an ELF file');
  }
  const is64 = buf[4] === 2;
  const le = buf[5] !== 2;

  const rd16 = (o) => (le ? buf.readUInt16LE(o) : buf.readUInt16BE(o));
  const rd32 = (o) => (le ? buf.readUInt32LE(o) : buf.readUInt32BE(o));
  const rd64 = (o) => (le
    ? Number(buf.readBigUInt64LE(o))
    : Number(buf.readBigUInt64BE(o)));

  let phoff, phentsize, phnum;
  if (is64) {
    phoff = rd64(0x20);
    phentsize = rd16(0x36);
    phnum = rd16(0x38);
  } else {
    phoff = rd32(0x1c);
    phentsize = rd16(0x2a);
    phnum = rd16(0x2c);
  }

  const out = {};

  for (let i = 0; i < phnum; i++) {
    const o = phoff + i * phentsize;
    if (o + phentsize > buf.length) break;

    let type, offset, vaddr, filesz, memsz;
    if (is64) {
      type = rd32(o);
      offset = rd64(o + 0x08);
      vaddr = rd64(o + 0x10);
      filesz = rd64(o + 0x20);
      memsz = rd64(o + 0x28);
    } else {
      type = rd32(o);
      offset = rd32(o + 0x04);
      vaddr = rd32(o + 0x08);
      filesz = rd32(o + 0x10);
      memsz = rd32(o + 0x14);
    }

    if (type !== 1 /* PT_LOAD */) continue;      // only memory-mapped segments
    if (filesz <= 0) continue;

    const fileStart = offset;
    const fileEnd = Math.min(offset + filesz, buf.length);
    if (fileStart >= fileEnd) continue;

    for (let a = vaddr; ; a += 4) {
      const rel = a - vaddr;
      if (rel + 4 > fileEnd - fileStart) break;
      const fo = fileStart + rel;
      if (fo % 1 !== 0 || fo + 4 > fileEnd) break;
      const v = le
        ? buf.readUInt32LE(fo)
        : buf.readUInt32BE(fo);
      out[String(a)] = v;
    }
  }

  return out;
}

const file = process.argv[2];
if (!file) {
  process.stderr.write('usage: node extract.js <elf-binary>\n');
  process.exit(1);
}
const result = extract(file);
process.stdout.write(JSON.stringify(result) + '\n');
