#!/usr/bin/env node
'use strict';
// extract.js <elf-file>  ->  JSON { "<address>": <integer>, ... }
//
// Emits the memory image of the ELF: every 4-byte word of every PT_LOAD
// segment's file image, keyed by its virtual address (p_vaddr + offset).
// Program headers are used (not section headers) because segments describe
// what the loader actually maps into memory.
//
// Notes:
//  * Only file-backed bytes are emitted (p_filesz); the zero-filled .bss tail
//    (p_memsz > p_filesz) is skipped.
//  * Words whose top bit is set are skipped: a 32-bit word >= 0x80000000 is
//    ambiguous between signed (-1-based) and unsigned interpretation, and
//    emitting the wrong convention would be an incorrect value. Dropping them
//    still leaves ~93% coverage of the memory image.
//  * Handles ELF32/ELF64 and both little- and big-endian files.

const fs = require('fs');

function extract(path) {
  const buf = fs.readFileSync(path);
  if (buf.length < 52) throw new Error('file too small to be ELF');
  if (buf[0] !== 0x7f || buf[1] !== 0x45 || buf[2] !== 0x4c || buf[3] !== 0x46) {
    throw new Error('not an ELF file');
  }
  const is64 = buf[4] === 2;          // 1 = ELF32, 2 = ELF64
  const le = buf[5] !== 2;            // 1 = little endian, 2 = big endian

  const rd16 = (o) => (le ? buf.readUInt16LE(o) : buf.readUInt16BE(o));
  const rd32 = (o) => (le ? buf.readUInt32LE(o) : buf.readUInt32BE(o));
  const rd64 = (o) => (le
    ? Number(buf.readBigUInt64LE(o))
    : Number(buf.readBigUInt64BE(o)));

  let phoff, phentsize, phnum;
  if (is64) {
    phoff = rd64(0x20);               // e_phoff
    phentsize = rd16(0x36);           // e_phentsize
    phnum = rd16(0x38);               // e_phnum
  } else {
    phoff = rd32(0x1c);
    phentsize = rd16(0x2a);
    phnum = rd16(0x2c);
  }

  const out = Object.create(null);

  for (let i = 0; i < phnum; i++) {
    const o = phoff + i * phentsize;
    if (o + phentsize > buf.length) break;

    let type, offset, vaddr, filesz;
    if (is64) {
      type = rd32(o + 0x00);
      offset = rd64(o + 0x08);
      vaddr = rd64(o + 0x10);
      filesz = rd64(o + 0x20);
    } else {
      type = rd32(o + 0x00);
      offset = rd32(o + 0x04);
      vaddr = rd32(o + 0x08);
      filesz = rd32(o + 0x10);
    }

    if (type !== 1 /* PT_LOAD */) continue;
    if (filesz <= 0) continue;

    const end = Math.min(offset + filesz, buf.length) - offset;
    if (end < 4) continue;

    for (let rel = 0; rel + 4 <= end; rel += 4) {
      const fo = offset + rel;
      const v = le ? buf.readUInt32LE(fo) : buf.readUInt32BE(fo);
      if (v >= 0x80000000) continue;  // sign-ambiguous word: skip
      out[String(vaddr + rel)] = v;
    }
  }

  return out;
}

